// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract DNSResolver {
    struct DNSRecord {
        bytes32 nameHash;
        address resolver;
        uint64 ttl;
        uint64 timestamp;
        bytes data;
    }

    struct CircuitBreaker {
        uint256 failureCount;
        uint256 lastFailureTime;
        uint256 cooldownPeriod;
        uint256 threshold;
        bool tripped;
    }

    mapping(bytes32 => DNSRecord) public records;
    mapping(address => CircuitBreaker) public breakers;
    mapping(bytes32 => bytes32[]) public subdomainChain;

    address public owner;
    uint256 public constant MAX_CHAIN_DEPTH = 16;
    uint256 public constant BREAKER_COOLDOWN = 300;
    uint256 public constant FAILURE_THRESHOLD = 5;

    event RecordResolved(bytes32 indexed nameHash, address resolver);
    event BreakerTripped(address indexed resolver, uint256 failures);
    event BreakerReset(address indexed resolver);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function registerRecord(
        bytes32 nameHash,
        address resolver,
        uint64 ttl,
        bytes calldata data
    ) external onlyOwner {
        records[nameHash] = DNSRecord({
            nameHash: nameHash,
            resolver: resolver,
            ttl: ttl,
            timestamp: uint64(block.timestamp),
            data: data
        });
        _initBreaker(resolver);
    }

    function registerSubdomainChain(
        bytes32 parentHash,
        bytes32[] calldata chain
    ) external onlyOwner {
        require(chain.length <= MAX_CHAIN_DEPTH, "Chain too deep");
        subdomainChain[parentHash] = chain;
    }

    function _initBreaker(address resolver) internal {
        if (breakers[resolver].cooldownPeriod == 0) {
            breakers[resolver] = CircuitBreaker({
                failureCount: 0,
                lastFailureTime: 0,
                cooldownPeriod: BREAKER_COOLDOWN,
                threshold: FAILURE_THRESHOLD,
                tripped: false
            });
        }
    }

    function _checkBreaker(address resolver) internal view returns (bool) {
        CircuitBreaker storage cb = breakers[resolver];
        if (!cb.tripped) return true;
        if (block.timestamp - cb.lastFailureTime >= cb.cooldownPeriod) {
            return true;
        }
        return false;
    }

    function _recordFailure(address resolver) internal {
        CircuitBreaker storage cb = breakers[resolver];
        cb.failureCount++;
        cb.lastFailureTime = block.timestamp;
        if (cb.failureCount >= cb.threshold) {
            cb.tripped = true;
            emit BreakerTripped(resolver, cb.failureCount);
        }
    }

    function _resetBreaker(address resolver) internal {
        CircuitBreaker storage cb = breakers[resolver];
        cb.failureCount = 0;
        cb.tripped = false;
        emit BreakerReset(resolver);
    }

    function resolveWithChain(
        bytes32 nameHash,
        uint256 depth
    ) public returns (bytes memory) {
        require(depth < MAX_CHAIN_DEPTH, "Max depth exceeded");

        DNSRecord storage record = records[nameHash];
        require(record.resolver != address(0), "Record not found");
        require(_checkBreaker(record.resolver), "Breaker tripped");

        if (block.timestamp - record.timestamp > record.ttl) {
            _recordFailure(record.resolver);
            revert("Record expired");
        }

        bytes32[] storage chain = subdomainChain[nameHash];
        if (chain.length > 0) {
            return _resolveChainRecursive(chain, 0, depth);
        }

        if (block.timestamp - record.timestamp <= record.ttl) {
            _resetBreaker(record.resolver);
        }

        emit RecordResolved(nameHash, record.resolver);
        return record.data;
    }

    function _resolveChainRecursive(
        bytes32[] storage chain,
        uint256 index,
        uint256 currentDepth
    ) internal returns (bytes memory) {
        if (index >= chain.length) {
            return "";
        }

        bytes32 currentHash = chain[index];
        DNSRecord storage current = records[currentHash];

        if (current.resolver == address(0)) {
            return "";
        }

        if (!_checkBreaker(current.resolver)) {
            return "";
        }

        bytes32[] storage nestedChain = subdomainChain[currentHash];
        bytes memory result;

        if (nestedChain.length > 0) {
            result = _resolveChainRecursive(nestedChain, 0, currentDepth + 1);
        } else {
            result = current.data;
        }

        bytes memory nextResult = _resolveChainRecursive(
            chain, index + 1, currentDepth
        );

        return _mergeResults(result, nextResult, currentDepth);
    }

    function _mergeResults(
        bytes memory a,
        bytes memory b,
        uint256 depth
    ) internal pure returns (bytes memory) {
        if (a.length == 0) return b;
        if (b.length == 0) return a;

        bytes memory merged = new bytes(a.length + b.length + 32);
        uint256 offset = 0;

        assembly {
            let aLen := mload(a)
            let bLen := mload(b)
            let mergedPtr := add(merged, 32)

            // Copy depth marker
            mstore(mergedPtr, depth)
            offset := 32

            // Copy a
            let aPtr := add(a, 32)
            for { let i := 0 } lt(i, aLen) { i := add(i, 32) } {
                mstore(add(mergedPtr, add(offset, i)), mload(add(aPtr, i)))
            }
            offset := add(offset, aLen)

            // Copy b
            let bPtr := add(b, 32)
            for { let i := 0 } lt(i, bLen) { i := add(i, 32) } {
                mstore(add(mergedPtr, add(offset, i)), mload(add(bPtr, i)))
            }
        }

        return merged;
    }

    function batchResolve(
        bytes32[] calldata nameHashes
    ) external returns (bytes[] memory) {
        bytes[] memory results = new bytes[](nameHashes.length);
        for (uint256 i = 0; i < nameHashes.length; i++) {
            try this.resolveWithChain(nameHashes[i], 0) returns (bytes memory data) {
                results[i] = data;
            } catch {
                results[i] = "";
            }
        }
        return results;
    }
}
